api.response_shapes:
// ---------------------------------------------------------------------------
// Fine — the object returned everywhere below. All Date fields serialize as
// ISO-8601 strings.
// ---------------------------------------------------------------------------
Fine = {
  id: string,
  memberId: string,
  loanId: string | null,              // null for ad-hoc fines never tied to a loan
  amountCents: integer,               // subunits. NEVER changes when paid/waived/voided
  currency: string,                   // ISO 4217, e.g. "EUR"
  reason: string,                     // why the money was owed, e.g. "4 day(s) overdue".
                                      // NOT overwritten by a waiver — see notes
  status: "outstanding" | "paid" | "waived",
  paidAt: string | null,              // ISO. Non-null ONLY for status "paid".
                                      // A waiver/void never sets it (no money moved)
  resolvedAt: string | null,          // ISO. null while outstanding. DERIVED:
                                      // paidAt for a payment, updatedAt for a
                                      // waiver/void (schema has no waivedAt)
  resolvedByUserId: string | null,    // control-plane User.id; null if an
                                      // impersonating Libriant admin did it
  notes: string | null,               // stamped disposition lines, newline-separated:
                                      //   "[<iso>] payment recorded — <notes>"
                                      //   "[<iso>] waived: <reason>"
                                      //   "[<iso>] voided (raised in error): <reason>"
  createdAt: string,                  // ISO
  updatedAt: string,                  // ISO
  member: { id: string, memberNumber: string, fullName: string,
            status: "active" | "suspended" | "archived" },
  loan: {
    id: string, dueAt: string, returnedAt: string | null,
    status: "active" | "returned" | "lost",
    copy: { id: string, barcode: string, book: { id: string, title: string } }
  } | null
}

MemberFinesSummary = {
  memberId: string,
  outstandingCount: integer,
  outstandingCents: integer,
  currency: string
}

// ---------------------------------------------------------------------------
// GET /t/:slug/fines  →  200
// ---------------------------------------------------------------------------
{
  items: Fine[],
  nextCursor: string | null,          // pass back as ?after=
  summary: MemberFinesSummary | null, // non-null ONLY when ?memberId= was sent.
                                      // Always counts OUTSTANDING under the same
                                      // member/loan filter, whatever ?status= says,
                                      // and is library-wide for that member — not
                                      // a total of the current page
  tenantSummary: { outstandingCount: integer, outstandingCents: integer, currency: string }
                                      // whole library, always present
}

// ---------------------------------------------------------------------------
// GET /t/:slug/fines/:id  →  200 Fine
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// POST /t/:slug/fines/:id/pay  →  200
//   request body (all optional; {} or no body is valid):
//     { amountCents?: integer 0..100000000, notes?: string (≤2000) }
//   SEND amountCents. It must equal the fine's CURRENT amount or the call is
//   refused — the nightly sweep grows a fine, so a screen that was rendered at
//   09:00 can be stale, and without it a €2.90 fine gets stamped "paid in full"
//   on the strength of €2.40 in the drawer.
//
// POST /t/:slug/fines/:id/waive  →  200
// POST /t/:slug/fines/:id/void   →  200
//   request body (reason REQUIRED):
//     { reason: string (3..500, trimmed), notes?: string (≤2000) }
//
// all three return the same envelope:
// ---------------------------------------------------------------------------
{
  fine: Fine,                         // the now-resolved fine
  member: MemberFinesSummary          // recomputed — use it to refresh the
                                      // member's "outstanding" total with no
                                      // second request
}

// ---------------------------------------------------------------------------
// Errors (HttpExceptionFilter passes these through verbatim)
// ---------------------------------------------------------------------------
400 validation      { statusCode: 400, message: string[] }   // e.g. missing reason
403 wrong role      { statusCode: 403, message: "This action is restricted to library admins." }
404 unknown/foreign { statusCode: 404, message: "Fine not found." }
409 already settled { statusCode: 409, error: "Conflict",
                      message: "This fine was already paid on 2026-08-25." | "This fine has already been written off.",
                      fineStatus: "paid" | "waived" | null }
409 stale amount    { statusCode: 409, error: "Conflict",
                      message: "This fine is now 2.90 EUR, not 2.40 EUR — it grew while the page was open. …",
                      currentAmountCents: integer, currency: string }
409 in flight       { statusCode: 409, message: "A previous identical request is still being processed. …" }
                    // same Idempotency-Key, first call not finished yet

// A REPLAYED Idempotency-Key returns 200 with the ORIGINAL body and the header
// X-Idempotent-Replay: true. Safe to treat identically to a first success.

// ---------------------------------------------------------------------------
// CHANGED — GET /t/:slug/members/:id
// ---------------------------------------------------------------------------
{ ...member, circulation: {
    activeLoans: integer,
    activeReservations: integer,
    outstandingFinesCents: integer,
    outstandingFinesCount: integer     // NEW. €0.00-across-two-fines and
                                       // no-fines-at-all are the same number,
                                       // so the count is what decides whether to
                                       // offer a settle action
}}

// ---------------------------------------------------------------------------
// CHANGED — POST /t/:slug/members/:id/erase, 400 refusal
// ---------------------------------------------------------------------------
{ statusCode: 400, message: "Can't erase a member with open business. …",
  activeLoans: integer, activeReservations: integer,
  outstandingFines: integer,
  outstandingFinesCents: integer }     // NEW
